// 1. 状态模式基础结构
public interface State {
    void handle(Context context);
}
public class ConcreteStateA implements State {
    @Override
    public void handle(Context context) {
        System.out.println("状态A处理");
        context.setState(new ConcreteStateB());
    }
}
public class ConcreteStateB implements State {
    @Override
    public void handle(Context context) {
        System.out.println("状态B处理");
        context.setState(new ConcreteStateA());
    }
}
public class Context {
    private State state;

    public Context(State state) {
        this.state = state;
    }

    public void setState(State state) {
        this.state = state;
    }

    public void request() {
        state.handle(this);
    }
}

// 2. 订单状态流转
public interface OrderState {
    void pay(Order order);
    void ship(Order order);
    void complete(Order order);
}
public class UnpaidState implements OrderState {
    @Override
    public void pay(Order order) {
        System.out.println("支付成功");
        order.setState(new PaidState());
    }

    @Override
    public void ship(Order order) {
        throw new IllegalStateException("未支付不能发货");
    }

    @Override
    public void complete(Order order) {
        throw new IllegalStateException("未支付不能完成");
    }
}
public class PaidState implements OrderState {
    @Override
    public void pay(Order order) {
        throw new IllegalStateException("已支付");
    }

    @Override
    public void ship(Order order) {
        System.out.println("发货成功");
        order.setState(new ShippedState());
    }

    @Override
    public void complete(Order order) {
        throw new IllegalStateException("未发货不能完成");
    }
}

// 3. 有限状态机
public class StateMachine {
    private State current;
    private Map<String, Map<String, State>> transitions = new HashMap<>();

    public void addTransition(String from, String event, String to) {
        transitions.computeIfAbsent(from, k -> new HashMap<>())
                   .put(event, getState(to));
    }

    public void trigger(String event) {
        Map<String, State> map = transitions.get(current.getName());
        if (map != null && map.containsKey(event)) {
            current = map.get(event);
            current.enter();
        }
    }
}
